import{_ as a,o as e,c as r,a2 as i}from"./chunks/framework.DA69LXMH.js";const p=JSON.parse('{"title":"Guia de Primeiro Uso","description":"","frontmatter":{},"headers":[],"relativePath":"guia/primeiro-uso.md","filePath":"guia/primeiro-uso.md"}'),s={name:"guia/primeiro-uso.md"};function n(t,o,d,l,c,u){return e(),r("div",null,[...o[0]||(o[0]=[i('<h1 id="guia-de-primeiro-uso" tabindex="-1">Guia de Primeiro Uso <a class="header-anchor" href="#guia-de-primeiro-uso" aria-label="Permalink to &quot;Guia de Primeiro Uso&quot;">​</a></h1><p>Bem-vindo ao <strong>EchoBot</strong>! Siga este tutorial passo a passo para configurar seu ambiente e conduzir sua primeira crônica de RPG do início ao fim.</p><hr><h2 id="⚙️-1-configuracoes-iniciais-provedores-de-ia" tabindex="-1">⚙️ 1. Configurações Iniciais &amp; Provedores de IA <a class="header-anchor" href="#⚙️-1-configuracoes-iniciais-provedores-de-ia" aria-label="Permalink to &quot;⚙️ 1. Configurações Iniciais &amp; Provedores de IA&quot;">​</a></h2><p>Antes de iniciar sua primeira mesa, abra o menu <strong>Configurações</strong> na barra superior para ajustar seus motores de preferência:</p><ol><li><strong>Aba IA (LLM):</strong><ul><li>Selecione seu provedor primário de narrativa. O <strong>Google Gemini</strong> é o padrão recomendado pela velocidade e custo, mas você pode utilizar <strong>OpenAI (GPT-4o)</strong>, <strong>Anthropic Claude 3.5</strong>, <strong>Groq</strong> ou <strong>OpenRouter</strong>.</li><li>Insira a chave de API correspondente.</li><li><em>(Opcional)</em> Configure provedores de <strong>Fallback</strong> na lista encadeada para contingência automática caso sua chave primária atinja limites de requisição.</li></ul></li><li><strong>Aba Áudio &amp; Voz:</strong><ul><li>Escolha o provedor de narração dos NPCs e resumos. Selecione <strong>Kokoro Local</strong> para síntese neural gratuita e offline, ou <strong>ElevenLabs / Deepgram</strong> para vozes customizadas em nuvem.</li></ul></li><li><strong>Aba Motor STT (Transcrição):</strong><ul><li>Confirme o modelo padrão: <strong><code>large-v3-turbo</code></strong> (com aceleração GPU) ou <code>tiny</code>/<code>base</code> (para computadores sem placa de vídeo).</li></ul></li><li><strong>Aba Discord (Se for gravar chamadas no Discord):</strong><ul><li>Cole o Token do seu Bot do Discord, Application ID e Public Key caso deseje utilizar o comando <code>/entrar</code> nos canais de voz.</li></ul></li></ol><hr><h2 id="🗺️-2-criando-seu-mundo-world" tabindex="-1">🗺️ 2. Criando seu Mundo (World) <a class="header-anchor" href="#🗺️-2-criando-seu-mundo-world" aria-label="Permalink to &quot;🗺️ 2. Criando seu Mundo (World)&quot;">​</a></h2><p>No EchoBot, a organização do seu universo segue uma hierarquia de 3 níveis: <strong>Mundos ➔ Campanhas ➔ Sessões</strong>.</p><ol><li>Na barra superior, clique em <strong>Mundos</strong> (ou navegue para <code>/worlds</code>).</li><li>Clique em <strong>Novo Mundo</strong>.</li><li>Defina o nome do seu cenário (ex: <em>&quot;Cenário de Tormenta - Arton&quot;</em> ou <em>&quot;Forgotten Realms - Faerûn&quot;</em>), selecione o sistema de regras (ex: <em>D&amp;D 5e, Tormenta20, Chamado de Cthulhu, Vampiro V20</em>, etc.) e faça upload de uma imagem de capa.</li><li>Seu mundo agora possui um <strong>Compêndio Enciclopédico</strong>, <strong>Grafo de Conhecimento</strong> e <strong>Oráculo RAG</strong> exclusivos!</li></ol><hr><h2 id="⚔️-3-criando-uma-campanha-mapeando-personagens" tabindex="-1">⚔️ 3. Criando uma Campanha &amp; Mapeando Personagens <a class="header-anchor" href="#⚔️-3-criando-uma-campanha-mapeando-personagens" aria-label="Permalink to &quot;⚔️ 3. Criando uma Campanha &amp; Mapeando Personagens&quot;">​</a></h2><p>Dentro do seu Mundo, crie a campanha dos seus aventureiros:</p><ol><li>Na página do Mundo, clique em <strong>Nova Campanha</strong> (ou na aba Campanhas).</li><li>Dê um nome à crônica (ex: <em>&quot;A Queda de Valkaria - Temporada 1&quot;</em>).</li><li>Na página da Campanha, clique em <strong>Mapear Personagens</strong>: <ul><li>Cadastre os personagens dos jogadores com nome, raça, classe e avatar.</li><li><strong>Vincular Discord ID:</strong> Permite que o EchoBot identifique automaticamente quem está falando durante as chamadas gravadas no Discord.</li><li><strong>Biometria Vocal (Opcional):</strong> Grave ou envie uma amostra de áudio de 15 segundos da voz do jogador para habilitar a identificação biométrica por IA.</li></ul></li></ol><hr><h2 id="🎙️-4-gravando-e-ingerindo-o-audio-da-sessao" tabindex="-1">🎙️ 4. Gravando e Ingerindo o Áudio da Sessão <a class="header-anchor" href="#🎙️-4-gravando-e-ingerindo-o-audio-da-sessao" aria-label="Permalink to &quot;🎙️ 4. Gravando e Ingerindo o Áudio da Sessão&quot;">​</a></h2><p>Abra sua campanha e clique em <strong>Nova Sessão</strong>. O EchoBot oferece <strong>4 formas flexíveis</strong> de capturar a partida:</p><h3 id="metodo-a-bot-de-voz-no-discord" tabindex="-1">Método A: Bot de Voz no Discord <a class="header-anchor" href="#metodo-a-bot-de-voz-no-discord" aria-label="Permalink to &quot;Método A: Bot de Voz no Discord&quot;">​</a></h3><ol><li>No canal de voz da sua mesa no Discord, digite o comando:<div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/entrar sessao_id:ID_DA_SUA_SESSAO</span></span></code></pre></div></li><li>O bot ingressará na chamada gravando as faixas de áudio isoladas de cada jogador.</li><li>Ao término da partida, digite <code>/sair</code> ou clique no botão de encerrar no Discord. O áudio será enviado automaticamente para a sessão.</li></ol><h3 id="metodo-b-gravador-webrtc-no-navegador" tabindex="-1">Método B: Gravador WebRTC no Navegador <a class="header-anchor" href="#metodo-b-gravador-webrtc-no-navegador" aria-label="Permalink to &quot;Método B: Gravador WebRTC no Navegador&quot;">​</a></h3><ol><li>Dentro dos detalhes da sessão no EchoBot, abra a caixa do <strong>Gravador WebRTC</strong>.</li><li>Selecione seu microfone e ative o botão opcional <strong>&quot;Capturar Áudio do Sistema&quot;</strong> (permitindo gravar o som do Discord ou Roll20 que sai no seu fone).</li><li>Clique em <strong>Iniciar Gravação</strong> e narre a sessão livremente pelo navegador.</li></ol><h3 id="metodo-c-upload-manual-em-lote-bulk-upload" tabindex="-1">Método C: Upload Manual em Lote (Bulk Upload) <a class="header-anchor" href="#metodo-c-upload-manual-em-lote-bulk-upload" aria-label="Permalink to &quot;Método C: Upload Manual em Lote (Bulk Upload)&quot;">​</a></h3><ol><li>Se você já gravou o áudio pelo OBS, Craig, Audacity ou gravador de celular, simplesmente arraste e solte múltiplos arquivos (<code>.mp3</code>, <code>.wav</code>, <code>.ogg</code>, <code>.m4a</code>) na área de upload.</li><li>O servidor converterá todos os arquivos silenciosamente para o formato otimizado Ogg/Opus.</li></ol><h3 id="metodo-d-importacao-direta-de-transcricao-md-txt" tabindex="-1">Método D: Importação Direta de Transcrição (.md / .txt) <a class="header-anchor" href="#metodo-d-importacao-direta-de-transcricao-md-txt" aria-label="Permalink to &quot;Método D: Importação Direta de Transcrição (.md / .txt)&quot;">​</a></h3><ol><li>Caso você possua um arquivo de texto já transcrito por outra ferramenta, clique no botão <strong>&quot;Importar Transcrição (.md)&quot;</strong>.</li><li>O parser inteligente interpretará oradores e timestamps, pulando a etapa de áudio e indo direto para o processamento de narrativa.</li></ol><hr><h2 id="🔮-5-processando-a-cronica-com-ia" tabindex="-1">🔮 5. Processando a Crônica com IA <a class="header-anchor" href="#🔮-5-processando-a-cronica-com-ia" aria-label="Permalink to &quot;🔮 5. Processando a Crônica com IA&quot;">​</a></h2><p>Com o áudio ou texto carregado na sessão:</p><ol><li>Clique em <strong>Processar com IA</strong>.</li><li>Acompanhe as barras de progresso dinâmicas: <ul><li><strong>Whisper Turbo:</strong> Transcrição precisa com timestamps e separação de falas.</li><li><strong>Identificação de Vozes:</strong> Correlaciona os padrões vocais aos personagens mapeados.</li></ul></li><li>Explore as abas geradas: <ul><li><strong>Transcrição:</strong> Revise as falas, alterne o botão <strong>IC / OOC</strong> (In-Character / Fora do Personagem) e faça ajustes rápidos.</li><li><strong>Diário Técnico:</strong> Consulte os NPCs encontrados, locais visitados, itens saqueados e o <strong>rastreador de Quests</strong> com status (<em>Ativa, Concluída, Falha</em>).</li><li><strong>Roteiro de Revisão:</strong> Leia a crônica épica em prosa e clique em <strong>Gerar Narração</strong> para sintetizar o áudio com voz neural e trilha sonora misturada.</li></ul></li></ol><hr><h2 id="🏰-6-alimentando-o-compendio-e-conectando-os-jogadores" tabindex="-1">🏰 6. Alimentando o Compêndio e Conectando os Jogadores <a class="header-anchor" href="#🏰-6-alimentando-o-compendio-e-conectando-os-jogadores" aria-label="Permalink to &quot;🏰 6. Alimentando o Compêndio e Conectando os Jogadores&quot;">​</a></h2><ul><li><strong>Sincronizar com o Compêndio:</strong> No Diário Técnico da sessão, clique em <strong>Sincronizar com a Wiki</strong> para transformar NPCs e locais encontrados em artigos permanentes no compêndio do mundo.</li><li><strong>Explorar o Grafo de Lore:</strong> Acesse a aba <strong>Grafo de Conhecimento</strong> no seu Mundo para ver visualmente como os personagens se conectam às cidades e facções.</li><li><strong>Compartilhar com Jogadores:</strong> No menu da campanha, abra o <strong>Portal do Jogador</strong>, copie o link do túnel seguro ou exiba o QR Code. Seus amigos poderão consultar a lore pública e submeter propostas diretamente pelo celular!</li></ul>',32)])])}const g=a(s,[["render",n]]);export{p as __pageData,g as default};
